export type AuditEvent = { readonly id: string; readonly createdAt: Date };

export function expired(events: readonly AuditEvent[], now: Date, retentionDays: number): readonly string[] {
  const cutoff = now.getTime() - retentionDays * 24 * 60 * 60 * 1000;
  return events.filter((event) => event.createdAt.getTime() < cutoff).map((event) => event.id);
}

export function batches(ids: readonly string[], size: number): readonly (readonly string[])[] {
  const result: string[][] = [];
  for (let offset = 0; offset < ids.length; offset += size) {
    result.push(ids.slice(offset, offset + size));
  }
  return result;
}

import { batches, expired, type AuditEvent } from './retention.ts';

export function planDeletion(events: readonly AuditEvent[], now: Date): readonly (readonly string[])[] {
  return batches(expired(events, now, 90), 100);
}

